import{_ as p,a0 as s,w as r,s as l,ao as b,I as a,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher","title":"每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher.md","filePath":"[post].md"}'),o={name:"201311/Daily Ubuntu Tips – Resize Ubuntu Unity Launcher.md"};function U(d,t,m,T,y,g){const u=s("Link");return r(),l("div",null,[t[11]||(t[11]=b('<h1 id="每日ubuntu小技巧-改變ubuntu-unity啓動器尺寸" tabindex="-1">每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸 <a class="header-anchor" href="#每日ubuntu小技巧-改變ubuntu-unity啓動器尺寸" aria-label="Permalink to “每日Ubuntu小技巧 - 改變Ubuntu Unity啓動器尺寸”">​</a></h1><p>這裏有一些給新Ubuntu用户的小技巧。這一系列的小技巧是為了幫助Ubuntu新用户輕鬆地配置和管理他們的電腦。這不是面向專家用户的，只是為了那些剛剛開始使用Ubuntu的用户。</p><p>Ubuntu啓動器是Ubuntu Unity桌面的關鍵部分。啓動器是一個佈滿圖標的垂直條，當你登陸的時候，它就會位於屏幕的左邊欄。通過它您可以從桌面方便地打開或者啓動程序，還可以讓您快速訪問應用、工作空間、可移動設備和垃圾桶。</p><p>默認情況下，這個啓動器圖標大小被設置為48X48px，即使是較小的屏幕上也如此。如果你需要調大或調小啓動器的尺寸，那麼請繼續接下來的學習。</p><p>想調整Unity啓動器尺寸的原因有很多。其中一個就是為了適應更小的屏幕。如果你的屏幕很小，默認尺寸不合適，那麼你就需要改變它了。</p><p>如果圖標默認尺寸太小，想要增大它，則可以調整啓動器來增大圖標，從而容易點擊。</p><p>下面開始調整大小，點擊右上角的齒輪按鈕彈出菜單條，點擊系統設置（System Settings...），如下圖。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntulockscreendisable3.png" alt=""></p><p>接下來，選擇 外觀（Appearance）</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/unitylauncherubuntu.png" alt=""></p><p>最後，使用滾動條來調整（增大\\減小）啓動器的圖標尺寸。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/unitylauncherubuntu1.png" alt=""></p><p>這個改變會被自動應用。記住，如果你想要繼續作用默認尺寸，移動到48.</p><p>這是另一個為Ubuntu新用户的小技巧。歡迎回來掌握更多的Ubuntu小技巧。如果你是一個老手並且想要做出貢獻，就請在下面留言吧。</p><h2 id="享受吧" tabindex="-1">享受吧！ <a class="header-anchor" href="#享受吧" aria-label="Permalink to “享受吧！”">​</a></h2>',15)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-resize-ubuntu-unity-launcher/"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-resize-ubuntu-unity-launcher/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原創翻譯，",-1)),e(u,{href:"http://linux.cn/"},{default:i(()=>[...t[3]||(t[3]=[n("Linux中國",-1)])]),_:1}),t[6]||(t[6]=n(" 榮譽推出",-1))]),a("p",null,[t[9]||(t[9]=n("譯者：",-1)),e(u,{href:"http://blog.csdn.net/vic___"},{default:i(()=>[...t[7]||(t[7]=[n("Vic___",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),e(u,{href:"https://github.com/jasminepeng"},{default:i(()=>[...t[8]||(t[8]=[n("jasminepeng",-1)])]),_:1})])])}const h=p(o,[["render",U]]);export{_ as __pageData,h as default};
